import './App.css';
import Layout from './Layout';
import About from './components/About';

function App() {
  return (
    <BrowserRouter>
    <Routes>
     <Route path='/' element={<Layout />} />
     <Route path='/About' element={<About />} />
     <Route path='/OnlineMenu' element={<OnlineMenu />} />
     </Routes>
    </BrowserRouter>

  );
}

export default App;
